head.script:
// 테스트 설명, 유효성 값 설정
//  - inputType 샘플 분리 : _1 입력창 편집형 / _2 아이템 선택형 / _3 편집 모드 미변경형 / _4 트리·텍스트이미지·Row 별 지정형 / _5 영역별 지원 속성값
//  - 본 샘플(_5) : 영역별(Header / Body / SubTotal / Footer) 지원 inputType 속성값과 동작 확인
//    inputType 은 가이드에 영역별 지원값이 명시되어 있어 Body 전용 관례의 예외로 Header / SubTotal / Footer Column 에도 설정
//    Body 의 각 inputType 값별 동작은 _1 ~ _4 에서 확인, 본 샘플은 Header checkbox 연동 대상(checkbox / radio / custom / text) 을 Body 에 둔다
scwin.tData = {
    "description" : "[column > P > inputType]<br/>Column 의 Cell 에 값을 표시하고 입력받는 방식을 설정합니다.",
    "validation" : [
        "전체 영역의 Column 에서 동작하며 영역마다 지원하는 속성값이 다릅니다.",
        "Column 의 영역에 따라 지원되는 inputType 속성값과 동작은 다음과 같습니다. Body 영역 : 모든 inputType 속성값을 지원하며 위의 속성 설명과 같이 동작합니다.",
        "Header 영역 'text' : value 속성값을 Cell 값으로 표시합니다.",
        "Header 영역 'checkbox' : 연관된 Body Column 이 'checkbox','radio','custom' 일 때만 연동되고, 그 외에는 체크 상태만 바뀝니다.",
        "Header 영역 'textImage' : value 속성값을 텍스트로 표시하고 viewType='icon' 이면 imageSrc 속성의 이미지를 함께 표시합니다.",
        "SubTotal/Footer 영역 'text' : value 속성값을 Cell 값으로 표시합니다.",
        "SubTotal/Footer 영역 'expression' : expression 속성의 계산식으로 산출한 값을 표시합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (viewType=icon)
    con_viewType.setValue("icon");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Header Column 정보 (Column 위치 순) / Body Column 정보 (Body Column 인덱스 순)
scwin.headerInfo = [
    { "id" : "h_cat",   "label" : "text" },
    { "id" : "h_chk",   "label" : "checkbox(Body checkbox)" },
    { "id" : "h_rdo",   "label" : "checkbox(Body radio)" },
    { "id" : "h_memo",  "label" : "checkbox(Body text)" },
    { "id" : "h_amt",   "label" : "textImage" },
    { "id" : "h_cus",   "label" : "checkbox(Body custom)" }
];
scwin.bodyInfo = [
    { "id" : "cat",  "label" : "분류" },
    { "id" : "chk",  "label" : "선택" },
    { "id" : "rdo",  "label" : "대표" },
    { "id" : "memo", "label" : "비고" },
    { "id" : "amt",  "label" : "금액" },
    { "id" : "cus",  "label" : "확인" }
];



// custom Column typeGetter : 모든 Row 를 checkbox 로 표시
scwin.fn_typeGetter = function (info) {
    return { "id" : "cus_" + info.realRowIndex + "_" + info.colIndex, "inputType" : "checkbox", "options" : {} };
}



// comp 생성
//  - Header : h_cat text / h_chk·h_rdo·h_memo·h_cus checkbox / h_amt textImage (imageSrc=ico_file.svg, viewType=con)
//  - Body   : cat text / chk checkbox / rdo radio / memo text / amt text(number) / cus custom(typeGetter -> checkbox) — custom 은 마지막 Column
//  - SubTotal(분류 기준) / Footer : 분류 위치 text, 금액 위치 expression
//  - checkbox / radio / custom 의 Body 데이터는 모두 체크 해제(0) 상태로 시작
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Header 체크박스 4개는 각각 Body checkbox / radio / text / custom(모든 Row checkbox) Column 위에 있음, Body 의 checkbox / radio / custom 은 모두 체크 해제 상태로 시작\n[전제] SubTotal 은 분류 기준, SubTotal / Footer 의 분류 위치는 text(소계 / 합계), 금액 위치는 expression(sum)\n[절차] Header 체크박스 클릭\n[확인] 클릭 시 Header 체크 상태와 Body DataList 값 자동 출력, (영역별 Cell 상태 확인) 버튼으로 영역별 표시값 확인"', '', 'label1');

    // 조건 (자체 값 select -> getValue, 미설정은 속성 자체를 넣지 않는다)
    let cViewType = con_viewType.getValue();
    let attrViewType = (cViewType === '') ? '' : ' viewType="' + cViewType + '"';

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList (body column id 와 동일한 컬럼 id 사용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cat" name="cat" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amt" name="amt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="cus" name="cus" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "cat" : "문구", "chk" : "0", "rdo" : "0", "memo" : "재고 부족", "amt" : 1200, "cus" : "0" },
        { "cat" : "문구", "chk" : "0", "rdo" : "0", "memo" : "정상",      "amt" : 3000, "cus" : "0" },
        { "cat" : "전자", "chk" : "0", "rdo" : "0", "memo" : "입고 예정", "amt" : 45000, "cus" : "0" }
    ], false);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" defaultCellHeight="30" id="" style="width:820px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="h_cat" value="분류"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="checkbox" id="h_chk" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="checkbox" id="h_rdo" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="checkbox" id="h_memo" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="textImage" imageSrc="/cm/images/base/ico_file.svg" id="h_amt" value="금액"' + attrViewType + '></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="checkbox" id="h_cus" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="cat" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="checkbox" id="chk" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="radio" id="rdo" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="memo" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" dataType="number" displayFormat="#,##0" id="amt" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="custom" typeGetter="scwin.fn_typeGetter" id="cus" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="cat">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="s_cat" value="소계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="s_chk" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="s_rdo" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="s_memo" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="expression" expression="sum(\'amt\')" displayFormat="#,##0" id="s_amt"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="s_cus" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row4">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="f_cat" value="합계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="f_chk" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="f_rdo" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="f_memo" value=""></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="expression" expression="sum(\'amt\')" displayFormat="#,##0" id="f_amt"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="f_cus" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // Header 체크박스 클릭 감지
    if (scwin["target1"]) {
        target1.render.addEventListener("click", scwin.onHeaderCheckClick, false);
    }
}



// Header Cell 상태 문자열
scwin.getHeaderDesc = function (info) {
    let td = document.querySelector("[id='" + target1.id + "_" + info.id + "']");
    if (!td) {
        return info.label + "=-";
    }
    let chk = td.querySelector("input[type='checkbox']");
    if (chk) {
        return info.label + "=체크박스 " + (chk.checked ? "체크" : "체크 해제");
    }
    if (info.label !== "textImage") {
        return info.label + "='" + td.textContent + "'";
    }
    let img = td.querySelector("img");
    return info.label + "='" + td.textContent + "'" + (img ? " + 이미지 " + (img.getAttribute("src") || "").split("?")[0] : " (이미지 없음)");
}



// validation 4 판정 출력 : Header 체크박스 클릭 후 Header 체크 상태와 아래 Body Column 의 DataList 값
scwin.onHeaderCheckClick = function (e) {
    let el = e.target;
    if (!el || el.tagName !== "INPUT" || el.type !== "checkbox") {
        return;
    }
    let info = null;
    for (let i = 0; i < scwin.headerInfo.length; i++) {
        let td = document.querySelector("[id='" + target1.id + "_" + scwin.headerInfo[i].id + "']");
        if (td && td.contains(el)) {
            info = scwin.headerInfo[i];
        }
    }
    if (!info) {
        return;
    }
    setTimeout(function () {
        let bodyId = info.id.replace("h_", "");
        wf_body_bottom.getObj("scwin").setReturnValue("Header " + info.label + " 클릭 -> Header 체크 : " + el.checked + " / Body " + bodyId + " (" + target1.getColumnType(bodyId) + ") DataList : " + dlt_bind.getColData(bodyId).join(", "));
    }, 100);
}



// validation 1 ~ 7 판정 출력 : 영역별 Cell 의 inputType 과 표시값
scwin.btn_checkAreaStatus_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    // Header
    let arrHeader = [];
    for (let i = 0; i < scwin.headerInfo.length; i++) {
        arrHeader.push(scwin.getHeaderDesc(scwin.headerInfo[i]));
    }
    bottom.setReturnValue("Header : " + arrHeader.join(" / "));

    // Body : Column inputType / Row 0 Cell 형태
    let arrBody = [];
    for (let c = 0; c < scwin.bodyInfo.length; c++) {
        let td = document.querySelector("[id='" + target1.id + "_cell_0_" + c + "']");
        let input = td ? td.querySelector("input") : null;
        arrBody.push(scwin.bodyInfo[c].label + "(" + target1.getColumnType(scwin.bodyInfo[c].id) + ")=" + (input ? "<input type=" + input.type + ">" : "'" + (td ? td.textContent : "-") + "'"));
    }
    bottom.setReturnValue("Body Row 0 : " + arrBody.join(" / "));

    // SubTotal : 표시 중인 SubTotal Row 별 분류 위치(text) / 금액 위치(expression)
    let arrSub = [];
    let subTrs = target1.render.querySelectorAll("tr[data-subtotalrowindex]");
    for (let i = 0; i < subTrs.length; i++) {
        if (subTrs[i].style.display === "none") {
            continue;
        }
        let sCat = subTrs[i].querySelector("td[id='s_cat']");
        let sAmt = subTrs[i].querySelector("td[id='s_amt']");
        arrSub.push("text='" + (sCat ? sCat.textContent : "-") + "', expression='" + (sAmt ? sAmt.textContent : "-") + "'");
    }
    bottom.setReturnValue("SubTotal (분류 기준) : " + arrSub.join(" / "));

    // Footer
    let fCat = document.querySelector("[id='" + target1.id + "_f_cat']");
    let fAmt = document.querySelector("[id='" + target1.id + "_f_amt']");
    bottom.setReturnValue("Footer : text='" + (fCat ? fCat.textContent : "-") + "' / expression='" + (fAmt ? fAmt.textContent : "-") + "' (금액 DataList : " + dlt_bind.getColData("amt").join(", ") + ")");
}
